#include <vector>
#include <string>
#include <queue>
#include <unordered_map>
#include <unordered_set>
#include <tuple>

class Solution {
public:
    int minMoves(std::vector<std::string>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        if (matrix[m - 1][n - 1] == '#') return -1;

        std::unordered_map<char, std::vector<std::pair<int, int>>> teleports;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                char c = matrix[i][j];
                if (c != '.' && c != '#') {
                    teleports[c].push_back({i, j});
                }
            }
        }

        std::vector<std::vector<int>> dist(m, std::vector<int>(n, 1e9));
        dist[0][0] = 0;
        using State = std::tuple<int, int, int>;
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
        pq.push({0, 0, 0});

        std::unordered_set<char> seen_t;
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        while (!pq.empty()) {
            auto [d, i, j] = pq.top();
            pq.pop();

            if (i == m - 1 && j == n - 1) return d;
            if (d > dist[i][j]) continue;

            char c = matrix[i][j];
            if (c >= 'A' && c <= 'Z' && !seen_t.count(c)) {
                seen_t.insert(c);
                for (const auto& [x, y] : teleports[c]) {
                    if (d < dist[x][y]) {
                        dist[x][y] = d;
                        pq.push({d, x, y});
                    }
                }
            }

            for (int k = 0; k < 4; ++k) {
                int x = i + dirs[k][0], y = j + dirs[k][1];
                if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] != '#') {
                    if (d + 1 < dist[x][y]) {
                        dist[x][y] = d + 1;
                        pq.push({d + 1, x, y});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minMoves(String[] matrix) {
        int m = matrix.length, n = matrix[0].length();
        if (matrix[m - 1].charAt(n - 1) == '#') return -1;

        Map<Character, List<int[]>> teleports = new HashMap<>();
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                char c = matrix[i].charAt(j);
                if (c != '.' && c != '#') {
                    teleports.computeIfAbsent(c, k -> new ArrayList<>()).add(new int[]{i, j});
                }
            }
        }

        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0, 0});
        Set<Character> seenT = new HashSet<>();
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], i = top[1], j = top[2];

            if (i == m - 1 && j == n - 1) return d;
            if (d > dist[i][j]) continue;

            char c = matrix[i].charAt(j);
            if (c >= 'A' && c <= 'Z' && !seenT.contains(c)) {
                seenT.add(c);
                List<int[]> portals = teleports.getOrDefault(c, Collections.emptyList());
                for (int[] pt : portals) {
                    int x = pt[0], y = pt[1];
                    if (d < dist[x][y]) {
                        dist[x][y] = d;
                        pq.offer(new int[]{d, x, y});
                    }
                }
            }

            for (int[] dir : dirs) {
                int x = i + dir[0], y = j + dir[1];
                if (x >= 0 && x < m && y >= 0 && y < n && matrix[x].charAt(y) != '#') {
                    if (d + 1 < dist[x][y]) {
                        dist[x][y] = d + 1;
                        pq.offer(new int[]{d + 1, x, y});
                    }
                }
            }
        }
        return -1;
    }
}

