var minMoves = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    if (matrix[m - 1][n - 1] === '#') return -1;

    const teleports = new Map();
    for (let i = 0; i < m; ++i) {
        for (let j = 0; j < n; ++j) {
            const c = matrix[i][j];
            if (c !== '.' && c !== '#') {
                if (!teleports.has(c)) teleports.set(c, []);
                teleports.get(c).push([i, j]);
            }
        }
    }

    const dist = Array.from({ length: m }, () => new Array(n).fill(Infinity));
    dist[0][0] = 0;

    // Simple priority queue or sorted array for Dijkstra
    const pq = [[0, 0, 0]];
    const seenT = new Set();
    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];

    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, i, j] = pq.shift();

        if (i === m - 1 && j === n - 1) return d;
        if (d > dist[i][j]) continue;

        const c = matrix[i][j];
        if (c >= 'A' && c <= 'Z' && !seenT.has(c)) {
            seenT.add(c);
            const portals = teleports.get(c) || [];
            for (const [x, y] of portals) {
                if (d < dist[x][y]) {
                    dist[x][y] = d;
                    pq.push([d, x, y]);
                }
            }
        }

        for (const [dx, dy] of dirs) {
            const x = i + dx, y = j + dy;
            if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] !== '#') {
                if (d + 1 < dist[x][y]) {
                    dist[x][y] = d + 1;
                    pq.push([d + 1, x, y]);
                }
            }
        }
    }
    return -1;
};
